INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1505748-ae398', 'stk-user9946', 'AE 398', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nاخواني انا محتار وين اتدرب فيه وماهي هي افضل الشركات للتدريب التعاوني(7 شهور) ونا قدامي خيارين\nالاول اني اتدرب بنفس منطقتي ولكن ما فيه شركات ممتازة\nالثاني اني اروح لشركة خارج المنطقة\nو الشركات خارج المنطقة واجد فيه منها شركات النفط (قطاع البترول والبتروكيماويات )و شركات انتاج الطاقة و شركات انتاج المواد الاساسية من النفط و شركات الطيران و شركات انتاج معدات ثقيلة و شركات التكييف يورك و GE و شركات السيارت\nو شركات كثير ولا اعلم ما اختار\n\nانا ارغب في شركه اتدرب فيها وبعد ما اتخرج واقدم على الوظائف استفيد منها في التقديم بحيث تكون في تخصصي ومرغوبه\n\n…\nوانا رحت للمسؤول عن التدريب التعاوني في كليتي وذكر لي شركات\nو المعهد العالي للمطاط بينبع ولا اخترت شي من اللي ذكر\nثم قالي شف الشركة اللي انت تبيها ونراسلهم لك\n\nولاني معطيه اسم شركة الا بعد ما اخذ رايكم\n\nالتخصص : هندسة ميكانيكية (علوم الميكانيكا )\nالمعدل : 3.1 من 5\n\nيهمني ان يكون لي سكن من الشركه\n\nواي معلومة عن التدريب التعاوني في الشركات ترها تفيدني\n\n*جامعتي ليست البترول والمعادن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/180992/1", "user": "user9946", "ts": 1549374542000, "tid": 180992, "pn": 1}}', 1549374542000, 1794826830, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1465920-ae398', 'stk-aatmah', 'AE 398', 'info', '{"desc": "نوع التدريب ( COOP )\nاسم الشركة أو جهة التدريب :\nAramco\nالسنة : 2015\nالتخصص + الجامعة: CHE-KFUPM\nمكان التدريب + القسم : تناجيب + Northern Area Technical support\nالمكافأة :4500 + بدلات + أوفر تايم = عليك الحساب\nطريقة التقديم : موقع الشركة\n\nإضافات\nتناجيب منطقة نائية والأغلب يستخدم طيران أرامكو للنقل\nالبيئة جميلة وهادية وكل شي متوفر\nبالنسبة للقسم كنت تبع الدعم الفني وشغلهم أغلبه مكتبي وممل\nلازم تبدأ بقوة من أول أسبوع وتحاول مع المنتور عشان يعطيك شغل ويطلعك معاهم الفيلد\n\nمزيد من الاستفسارات على الرحب والسعة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/57", "user": "AATMAH", "ts": 1483803721000, "tid": 170460, "pn": 57}}', 1483803721000, 1794826830, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1227621-ae398', 'stk-a7md_i', 'AE 398', 'info', '{"desc": "السلام عليكم ورحمه الله وبركاته\n\nاخواني انا جتني رساله من ارامكو فيها موعد لاصدار البطاقه في الظهران\n28 مايو الساعه 9 صباحاً\n\nوانا الصراحه مو من الشرقيه … هل يوفرون لي تذاكر طيران من ارامكو ؟\nووش المطلوب مني بالضبط في ذاك اليوم … هل هو مجرد حضور واستلام بطاقه وخلاص !\nووين مكانه في المبنى الرئيسي في الظهران ولا وين ؟\n\nوالله يعطيكم العافيه\n\nيمديك تسويه في أي مكتب لأرامكو حسب ما أعرف شوف الموضوع\nhttp://www.skaau.com/vb/showthread.php?p=6549141#post6549141", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/144977/7", "user": "a7md_i", "ts": 1369475262000, "tid": 144977, "pn": 7}}', 1369475262000, 1794826830, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1457455-ae398', 'stk-heshy', 'AE 398', 'info', '{"desc": "بجاوبك كطالب في نفس التخصص،\n\nبما انك ابلايد يفضل انك تزود سمستر واحد على التخرج ، تصير الخطة زي ما قال اخونا @Bo Rayan\nالكوأب يبدأ سمستر ثاني وينتهي صيف ، والسمستر اللي بعده يكون اخر سمستر لك\n\nالسبب لان كل مواد التخصص التقريبا تكون نازلة في السمستر الاول ، تقدر تنزل منها ما تشاء لانها بدون تعارضات غالبا في الوقت ،\n\nاذا بتاخذ الكوأب في شركة طيران مثل الخطوط ينصح وبشدة تاخذ AE401 من لستة الاليكتف قبل ما تروح لانها عن صيانة انظمة الطيران والفضاء\n\nولو انت بتاخذه في شركة تصميم وتصنيع ما تحتاجها كثير او بالاحرى ما تحتةجها ابدا مثل ما صار معاي\n\nونقطة اخيرة خلص كورسات التخصص لفل 3 قبل ما تطلع قدر الامكان ، لانها اساسات التخصص وهي اللي بتخليك عارف كل شي\n\nوحاول قدر الامكان تاخر الكوأب لان الشركة اللي تطبق فيها غالبا تتوظف فيها .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/174616/5", "user": "HESHY", "ts": 1473569195000, "tid": 174616, "pn": 5}}', 1473569195000, 1794826830, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p567989-ae398', 'stk-eminem', 'AE 398', 'info', '{"desc": "هلا أخوي: أنا طالب AE Sr طبقت في شركة السلام للطائرات سمر تريننق\n\nشوف: صراحة التطبيق كان مفيد بحيث انك تشوف طبيعت عملك كمهندس هياكل طائرات على أرض الواقع . لكن الشركة شوي ملخبطه يعني لمى تجي تحس انو مافيه أحد مهتم فيك وهذا طبيعة أغلب الشركات في السعوديه\n\nبالنسبه للي أسمعه أنا: الخطوط السعوديه عندهم برامج أكثر من رائعه للتدريب وعندهم أيضا مشاريع جباره على الطائرات فشوف أنت وين ترتاح أكثر. وفيه شركات ثانيه مثل شلمبرجير (قبلت زميلي أيروسبيس كوأب),BAE جدا حلوه , وغيرها الكثر\n\nبرى السعوديه فيه أعرف واحد انقبل في إيرباص وبوينج كتدريب . حاول وشوف …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-training/85431/4", "user": "eminem", "ts": 1268829819000, "tid": 85431, "pn": 4}}', 1268829819000, 1794826830, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
